-- CRM CPP · Paso 3: plantillas de WhatsApp (reemplaza las del equipo por estas versiones)
insert into public.docs (collection, id, data)
select 'templates', t.id, jsonb_build_object('name', t.name, 'order', t.ord, 'body', t.body, 'updatedAt', now()::text, 'updatedBy', null)
from (values
('tpl-01',E'Primer contacto',1,E'Hola, ¿qué tal? Soy {mi_nombre}, de CPP. Encontré {negocio} en Google Maps y vi que todavía no tiene página web.\n\nHacemos páginas web para negocios de {ciudad}. Para un negocio como el suyo, la web puede {idea}.\n\n✅ Aparece cuando lo buscan en Google\n✅ WhatsApp, ubicación y horarios en un solo lugar\n✅ Se ve bien en celular y computadora\n✅ Desde S/ 300\n\nAquí puede ver nuestro trabajo: https://cppcstudio.com/#proyectos\nPor ejemplo, {ejemplo}.\n\n¿Le gustaría que le muestre una idea de cómo se vería la página de {negocio}? Es sin compromiso.'),
('tpl-02',E'Envío de ejemplos y precios',2,E'¡Gracias por responder! Le cuento un poco más:\n\n🌐 Nuestra web: https://cppcstudio.com\n📂 Proyectos reales: https://cppcstudio.com/#proyectos\nPor ejemplo, {ejemplo}.\n\nPara {negocio} podríamos hacer:\n• Landing page (una página con todo lo importante): desde S/ 300\n• Página web con varias secciones: desde S/ 500\n• Catálogo digital de productos o servicios: desde S/ 500\n\nLa idea es que su web pueda {idea}.\n\n¿Qué le gustaría que muestre su página? Con eso le preparo una propuesta a medida, sin compromiso.'),
('tpl-03',E'Seguimiento sin respuesta',3,E'Hola, ¿cómo le va? Soy {mi_nombre}, de CPP. Hace unos días le escribí sobre una página web para {negocio}.\n\nLe dejo nuestro trabajo por si quiere verlo con calma: https://cppcstudio.com/#proyectos\n\nHoy mucha gente busca en Google antes de llamar o visitar un negocio. Con su propia web, a {negocio} lo encuentran más fácil y le escriben directo por WhatsApp.\n\nSi le interesa, le preparo una propuesta sin compromiso. ¿Le parece?'),
('tpl-04',E'Envío de propuesta',4,E'Hola {contacto}, le comparto la propuesta para la página web de {negocio}. Incluye lo que conversamos, el precio y lo que necesitaríamos de su parte.\n\nMientras la revisa, aquí puede ver otros trabajos nuestros: https://cppcstudio.com/#proyectos\n\nQuedo atento a sus comentarios. Si prefiere, coordinamos una llamada corta para revisarla juntos.'),
('tpl-05',E'Guion de llamada (teléfono fijo)',5,E'Buenos días, ¿hablo con {negocio}? Mi nombre es {mi_nombre}, de CPP. Hacemos páginas web y sistemas para negocios de {ciudad}.\n\nLe llamo porque encontramos su negocio en Google Maps y vimos que todavía no tiene página web. Para un negocio como el suyo, la web puede {idea}.\n\n¿Con quién podría conversar sobre eso?\n\nSi muestra interés: pedir un WhatsApp o correo para enviarle ejemplos (https://cppcstudio.com/#proyectos) y una propuesta. Precios desde S/ 300.'),
('tpl-06',E'Último mensaje (cierre amable)',6,E'Hola, le escribe {mi_nombre} de CPP. Este es mi último mensaje sobre la página web para {negocio}, para no incomodarle.\n\nSi más adelante le interesa, aquí puede ver nuestro trabajo y escribirnos cuando quiera: https://cppcstudio.com\n\n¡Muchos éxitos con {negocio}!')
) as t(id, name, ord, body)
on conflict (collection, id) do update set data = excluded.data, updated_at = now();

select id, data->>'name' as nombre, length(data->>'body') as largo from public.docs where collection = 'templates' order by data->>'order';
